"""Constructor argument checks for permission data generated by catalog metadata."""

import pytest

from xbsl import engine


pytestmark = pytest.mark.needs_data
RULE = "code/constructor-argument-type"

CATALOG = """ВидЭлемента: Справочник
Имя: Детали
КонтрольДоступа:
    РасчетРазрешенийПо:
        - Код
    Разрешения:
        Чтение: РазрешенияВычисляютсяДляКаждогоОбъекта
Реквизиты:
    -
        Имя: Код
        Тип: Число
"""


def _lint(expression, catalog=CATALOG):
    module = (
        "метод Собрать(Элемент: Детали.Объект)\n"
        f"    знч Данные = новый Детали.ДанныеРасчетаРазрешений({expression})\n"
        ";\n"
    )
    return engine.run_sources(
        [engine.load_text("Детали.yaml", catalog), engine.load_text("Проверка.xbsl", module)],
        select={RULE},
    )


@pytest.mark.parametrize("expression", ["Элемент.Ссылка", "Код = Элемент.Ссылка"])
def test_reference_cannot_fill_numeric_permission_key(expression):
    findings = _lint(expression)
    assert len(findings) == 1
    assert findings[0].rule_id == RULE
    assert findings[0].path == "Проверка.xbsl" and findings[0].line == 2
    assert "Код" in findings[0].message


@pytest.mark.parametrize("expression", ["Элемент.Код", "Код = 12", "Элемент", "Неизвестный()"])
def test_valid_overload_or_unknown_argument_is_not_reported(expression):
    assert _lint(expression) == []


def test_reference_is_valid_when_the_permission_key_is_a_reference():
    assert _lint("Элемент.Ссылка", CATALOG.replace("Тип: Число", "Тип: Детали.Ссылка")) == []


def test_english_facet_and_reference_are_resolved():
    module = (
        "method Build(Item: Детали.Object)\n"
        "    val Data = new Детали.PermissionsComputeData(Item.Reference)\n"
        ";\n"
    )
    findings = engine.run_sources(
        [engine.load_text("Детали.yaml", CATALOG), engine.load_text("Probe.xbsl", module)],
        select={RULE},
    )
    assert len(findings) == 1
    assert findings[0].rule_id == RULE
